<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Midnight Ramen</title>
<style>
  :root{
    --bg-deep:#0b0708;
    --bg-mid:#171014;
    --warm:#ff9a3c;
    --ember:#ff5a2a;
    --gold:#ffc36b;
    --cream:#f5e6d0;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{height:100%;overflow:hidden}
  body{
    background:var(--bg-deep);
    font-family:Georgia,serif;
    display:flex;align-items:center;justify-content:center;
    cursor:crosshair;
  }
  .stage{
    position:relative;
    width:100vmin;height:100vmin;
    max-width:100%;max-height:100%;
    aspect-ratio:1/1;
  }
  /* ambient background wash */
  .ambient{
    position:absolute;inset:0;
    background:
      radial-gradient(ellipse 90% 70% at 50% 62%, #3a1d12 0%, #241019 42%, #120b0f 68%, var(--bg-deep) 100%);
    pointer-events:none;
  }
  .ambient::after{
    content:"";position:absolute;inset:0;
    background:radial-gradient(ellipse 55% 40% at 50% 68%, rgba(255,150,60,.28) 0%, transparent 70%);
    animation:breathe 6s ease-in-out infinite;
  }
  @keyframes breathe{0%,100%{opacity:.75;transform:scale(1)}50%{opacity:1;transform:scale(1.08)}}

  /* floor reflection glow */
  .glow{
    position:absolute;left:50%;bottom:6%;
    width:72%;height:16%;
    transform:translateX(-50%);
    background:radial-gradient(ellipse at center, rgba(255,140,50,.35) 0%, rgba(255,90,30,.12) 45%, transparent 75%);
    filter:blur(10px);
    animation:glowPulse 4.5s ease-in-out infinite;
    pointer-events:none;
  }
  @keyframes glowPulse{0%,100%{opacity:.7}50%{opacity:1}}

  /* light rays */
  .rays{position:absolute;left:50%;top:-10%;transform:translateX(-50%);width:120%;height:80%;pointer-events:none;
    background:conic-gradient(from 180deg at 50% 0%, transparent 40%, rgba(255,190,110,.07) 46%, transparent 52%, transparent 58%, rgba(255,170,90,.05) 63%, transparent 70%);
    filter:blur(14px);animation:raySway 9s ease-in-out infinite;
  }
  @keyframes raySway{0%,100%{transform:translateX(-50%) rotate(-2deg)}50%{transform:translateX(-50%) rotate(2deg)}}

  /* the scene group for parallax */
  .scene{
    position:absolute;inset:0;
    transform-style:preserve-3d;
    will-change:transform;
    transition:transform .35s cubic-bezier(.2,.8,.2,1);
  }
  .ramen-wrap{position:absolute;left:50%;top:52%;width:78%;aspect-ratio:1/1;transform:translate(-50%,-50%);will-change:transform;}

  svg.ramen{width:100%;height:100%;overflow:visible;display:block}

  /* steam canvas */
  #steam{position:absolute;left:0;top:-6%;width:100%;height:72%;pointer-events:none;z-index:5}

  /* floating ember particles */
  #embers{position:absolute;inset:0;pointer-events:none;z-index:1}

  /* rim light sweep */
  .sweep{
    position:absolute;inset:0;border-radius:50%;
    background:radial-gradient(ellipse 60% 45% at 50% 45%, transparent 55%, rgba(0,0,0,.55) 100%);
    pointer-events:none;z-index:9;
    mix-blend-mode:multiply;
  }

  @media (prefers-reduced-motion: reduce){
    *,*::before,*::after{animation:none !important;transition:none !important}
    .scene,.ramen-wrap{transform:none !important}
  }
</style>
</head>
