  <div class="scene" id="scene">
    <div class="ramen-wrap" id="ramenWrap">
      <svg class="ramen" viewBox="0 0 600 520" aria-hidden="true">
        <defs>
          <radialGradient id="brothGrad" cx="50%" cy="42%" r="65%">
