        </defs>

        <!-- table shadow -->
        <ellipse cx="300" cy="452" rx="205" ry="36" fill="url(#shadowGrad)"/>
        <ellipse cx="300" cy="452" rx="150" ry="22" fill="#000" opacity=".5" filter="url(#soft)"/>

        <!-- bowl body -->
        <path d="M 118 262 Q 118 420 300 420 Q 482 420 482 262 Z" fill="url(#bowlGrad)"/>
        <path d="M 118 262 Q 118 420 300 420 Q 482 420 482 262 Z" fill="none" stroke="#000" stroke-opacity=".4" stroke-width="2"/>
        <!-- bowl warm inner rim light -->
        <path d="M 118 262 Q 118 300 132 336" fill="none" stroke="#ff9a3c" stroke-opacity=".35" stroke-width="5" stroke-linecap="round" filter="url(#soft2)"/>
        <path d="M 482 262 Q 482 300 468 336" fill="none" stroke="#ff9a3c" stroke-opacity=".22" stroke-width="4" stroke-linecap="round" filter="url(#soft2)"/>
