  <div class="sweep"></div>
</div>

<script>
(function(){
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const stage = document.getElementById('stage');
  const scene = document.getElementById('scene');
  const wrap = document.getElementById('ramenWrap');
  const steamC = document.getElementById('steam');
  const emberC = document.getElementById('embers');
  const sctx = steamC.getContext('2d');
  const ectx = emberC.getContext('2d');

  let W=0,H=0,dpr=Math.min(window.devicePixelRatio||1,2);

  function fit(){
    const r = stage.getBoundingClientRect();
    W = r.width; H = r.height;
    stage.style.setProperty('--w', W+'px');
    // embers canvas: full stage
    emberC.width = W*dpr; emberC.height = H*dpr;
    emberC.style.width=W+'px'; emberC.style.height=H+'px';
    ectx.setTransform(dpr,0,0,dpr,0,0);
    // steam canvas: inside wrap
    const wr = wrap.getBoundingClientRect();
    steamC.width = wr.width*dpr; steamC.height = wr.height*dpr;
    steamC.style.width=wr.width+'px'; steamC.style.height=wr.height+'px';
    sctx.setTransform(dpr,0,0,dpr,0,0);
  }

  // steam particles
  const steam = [];
  function spawnSteam(){
    const rect = wrap.getBoundingClientRect();
    steam.push({
      x: rect.width*(0.36 + Math.random()*0.28),
      y: rect.height*0.30,
      r: 10+Math.random()*16,
      vy: -(0.35+Math.random()*0.45),
      vx: (Math.random()-0.5)*0.3,
      life: 0, max: 140+Math.random()*80,
      wob: Math.random()*Math.PI*2, wobSpd: 0.012+Math.random()*0.02
    });
  }
  // embers
  const embers = [];
  function spawnEmber(){
    const r = stage.getBoundingClientRect();
    embers.push({
      x: r.width*(0.3+Math.random()*0.4),
      y: r.height*(0.55+Math.random()*0.35),
      r: 0.6+Math.random()*1.6,
      vy: -(0.15+Math.random()*0.4),
      vx: (Math.random()-0.5)*0.25,
      life: 0, max: 180+Math.random()*160,
      hue: 18+Math.random()*30
    });
  }

  let mouseX=0.5, mouseY=0.45, tMouseX=0.5, tMouseY=0.45;
  let scent=0; // scent strength 0..1, increases near bowl

  window.addEventListener('pointermove', e=>{
    const r = stage.getBoundingClientRect();
    tMouseX = (e.clientX-r.left)/r.width;
    tMouseY = (e.clientY-r.top)/r.height;
  }, {passive:true});

  const noodleGroup = document.getElementById('noodles');
  const greens = document.getElementById('greens');
  const scallions = document.getElementById('scallions');

  let t=0;
  function frame(){
    t++;
    mouseX += (tMouseX-mouseX)*0.06;
    mouseY += (tMouseY-mouseY)*0.06;

    // parallax
    const dx = (mouseX-0.5), dy=(mouseY-0.45);
    if(!reduce){
      scene.style.transform = `translate3d(${dx*-26}px, ${dy*-18}px, 0)`;
      wrap.style.transform = `translate(-50%,-50%) translate3d(${dx*14}px, ${dy*10}px, 0) rotate(${dx*1.6}deg)`;
    }

    // scent: proximity to bowl center
    const bowlX = 0.5, bowlY = 0.52;
    const dist = Math.hypot(mouseX-bowlX, mouseY-bowlY);
    const target = Math.max(0, 1 - dist*2.4);
    scent += (target-scent)*0.04;

    // draw steam
    const wr = wrap.getBoundingClientRect();
    const ww = steamC.width/dpr, wh = steamC.height/dpr;
    sctx.clearRect(0,0,ww,wh);
    if(!reduce && steam.length < 46){
      const rate = 1 + Math.floor(scent*3);
      for(let i=0;i<rate;i++) if(Math.random()<0.75) spawnSteam();
    }
    for(let i=steam.length-1;i>=0;i--){
      const p = steam[i];
      p.life++; p.y += p.vy*(1+scent*0.6); p.x += p.vx + Math.sin(p.wob + p.life*0.02)*0.45;
      p.wob += p.wobSpd;
      p.r += 0.16;
      if(p.life>p.max || p.y<wh*0.02){ steam.splice(i,1); continue; }
      const a = Math.sin((p.life/p.max)*Math.PI) * (0.16 + scent*0.16);
      const grad = sctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r*2.4);
      grad.addColorStop(0,`rgba(255,240,225,${a})`);
      grad.addColorStop(0.55,`rgba(255,225,205,${a*0.45})`);
      grad.addColorStop(1,'rgba(255,225,205,0)');
      sctx.fillStyle = grad;
      sctx.beginPath();
      sctx.arc(p.x,p.y,p.r*2.4,0,Math.PI*2);
      sctx.fill();
    }

    // embers
    const r = stage.getBoundingClientRect();
    ectx.clearRect(0,0,r.width,r.height);
    if(!reduce && embers.length < 34 && Math.random()<0.35) spawnEmber();
    for(let i=embers.length-1;i>=0;i--){
      const p = embers[i];
      p.life++; p.y += p.vy; p.x += p.vx + Math.sin((p.life+p.hue)*0.03)*0.25;
      if(p.life>p.max){ embers.splice(i,1); continue; }
      const a = Math.sin((p.life/p.max)*Math.PI);
      ectx.beginPath();
      ectx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ectx.fillStyle = `hsla(${p.hue},95%,62%,${a*0.75})`;
      ectx.shadowColor = `hsla(${p.hue},95%,55%,.9)`;
      ectx.shadowBlur = 8;
      ectx.fill();
      ectx.shadowBlur = 0;
    }

    // subtle noodle sway (SVG transform)
    if(!reduce){
      const sway = Math.sin(t*0.02)*2.2 + dx*5;
      noodleGroup.setAttribute('transform',`translate(${sway} 0)`);
      greens.setAttribute('transform',`translate(${sway*0.6} 0) rotate(${sway*0.5} 300 245)`);
      scallions.setAttribute('transform',`translate(${sway*0.8} 0)`);
    }

    if(!reduce) requestAnimationFrame(frame);
  }

  window.addEventListener('resize', ()=>{ fit(); });
  fit();
  if(reduce){
    // draw one static frame of steam
    for(let i=0;i<18;i++) spawnSteam();
    steam.forEach(p=>{ p.life = p.max*0.5; p.y -= 30+Math.random()*40; });
    (function drawStatic(){
      const wr = steamC.getBoundingClientRect();
      const ww = steamC.width/dpr, wh = steamC.height/dpr;
      steam.forEach(p=>{
        const a = 0.14;
        const grad = sctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r*2.4);
        grad.addColorStop(0,`rgba(255,240,225,${a})`);
        grad.addColorStop(1,'rgba(255,225,205,0)');
        sctx.fillStyle=grad; sctx.beginPath(); sctx.arc(p.x,p.y,p.r*2.4,0,Math.PI*2); sctx.fill();
      });
    })();
  } else {
    frame();
  }
  // keep fitting on orientation change
  window.addEventListener('orientationchange', ()=>setTimeout(fit,120));
})();
</script>
</body>
</html>
